-- Bulkify · 010 · built-in exercise library (592 exercises, EN + AR). Generated by tools/gen_seeds.py. Re-runnable.
on conflict (slug) where owner_id is null do update set name_en = excluded.name_en, name_ar = excluded.name_ar,
  primary_muscle = excluded.primary_muscle, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment;
